'use strict';
const $=id=>document.getElementById(id),defaults={speed:40,size:38,width:86,delay:3,double:false,mirror:false,flip:false,showGuide:true,font:'sans-serif',color:'#f4f4ee'};
const welcome=`Every great story starts with a voice.\n\nNot a perfect voice. Your voice.\n\nTake a breath. Find your pace. And let the words do what they came here to do.\n\nThis is your space to write, rehearse, and deliver with confidence.\n\nUse the arrow keys to find your rhythm. Up to go faster. Down to take your time. Press Space whenever you need a moment.\n\nWhen you're ready for another take, press T to start again.\n\nThe floor is yours.`;
let docs=[],current,settings={...defaults},playing=false,position=0,last=0,elapsed=0,countTimer=null,wake=null,frame=0;
try{const data=JSON.parse(localStorage.getItem('cue-studio-v1')||'null');if(data&&Array.isArray(data.docs)&&data.docs.length){docs=data.docs;current=data.current;settings={...defaults,...data.settings};}}catch{}
if(!docs.length){docs=[{id:crypto.randomUUID(),title:'A little confidence, on cue',text:welcome}];current=docs[0].id;}if(!docs.some(d=>d.id===current))current=docs[0].id;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
function persist(){try{localStorage.setItem('cue-studio-v1',JSON.stringify({docs,current,settings}));$('saveState').textContent='● Saved on this device';}catch{$('saveState').textContent='⚠ Not saved — export a backup';}}
function text(){return $('editor').innerText.replace(/\r/g,'');}
function currentDoc(){return docs.find(d=>d.id===current);}
function list(){const select=$('scripts');select.replaceChildren(...docs.map(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.title||'Untitled script';return o;}));select.value=current;}
function updateText(){const value=text();$('promptText').textContent=value;const words=value.trim().split(/\s+/).filter(Boolean).length;$('wordCount').textContent=`${words} words`;$('readTime').textContent=`~${Math.floor(words/130)}:${String(Math.round(words/130*60)%60).padStart(2,'0')} at 130 wpm`;}
function saveDoc(){const d=currentDoc();d.title=$('title').value;d.text=text();d.html=$('editor').innerHTML;updateText();persist();list();}
function safeHTML(html){const t=document.createElement('template');t.innerHTML=html;const allowed=new Set(['B','STRONG','I','EM','U','BR','P','DIV']);function clean(node){for(const c of [...node.children]){if(!allowed.has(c.tagName)){c.replaceWith(document.createTextNode(c.textContent));}else{for(const a of [...c.attributes])c.removeAttribute(a.name);clean(c);}}}clean(t.content);return t.innerHTML;}
function loadDoc(){pause();const d=currentDoc();$('title').value=d.title;if(d.html)$('editor').innerHTML=safeHTML(d.html);else $('editor').textContent=d.text||'';list();updateText();reset();persist();}
function apply(){for(const key of ['speed','size','width','delay','font'])$(key).value=settings[key];for(const key of ['double','mirror','flip','showGuide'])$(key).checked=settings[key];$('speedLabel').textContent=$('speedOut').textContent=settings.speed;$('sizeOut').textContent=settings.size+' px';$('widthOut').textContent=settings.width+'%';const p=$('promptText');p.style.fontSize=settings.size+'px';p.style.width=settings.width+'%';p.style.lineHeight=settings.double?'2':'1.5';p.style.fontFamily=settings.font;p.style.color=settings.color;p.style.transform=`scale(${settings.mirror?-1:1},${settings.flip?-1:1})`;$('guide').hidden=!settings.showGuide;$('guide').style.height=settings.size*(settings.double?2:1.5)+'px';document.querySelectorAll('.swatch').forEach(b=>b.classList.toggle('selected',b.dataset.color===settings.color));persist();}
function changeSpeed(delta){settings.speed=Math.max(5,Math.min(160,Number(settings.speed)+delta));apply();}
async function keepAwake(){try{if('wakeLock'in navigator)wake=await navigator.wakeLock.request('screen');}catch{}}
function release(){if(wake){wake.release().catch(()=>{});wake=null;}}
function status(){const pending=countTimer!==null;$('play').innerHTML=playing?'Ⅱ <span>Pause scrolling</span>':pending?'■ <span>Cancel countdown</span>':'▶ <span>Start scrolling</span>';$('status').textContent=playing?'ROLLING':pending?'STAND BY':'READY';}
function pause(){playing=false;cancelAnimationFrame(frame);if(countTimer!==null){clearInterval(countTimer);countTimer=null;}$('countdown').hidden=true;release();status();}
function reset(){pause();position=0;elapsed=0;$('viewport').scrollTop=0;progress();}
function progress(){const v=$('viewport'),max=v.scrollHeight-v.clientHeight;$('percent').textContent=(max>0?Math.round(v.scrollTop/max*100):0)+'%';$('elapsed').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');}
function tick(now){if(!playing)return;const dt=Math.min((now-last)/1000,.1);last=now;elapsed+=dt;position+=settings.speed*dt;const v=$('viewport');v.scrollTop=position;progress();if(position>=v.scrollHeight-v.clientHeight){pause();$('status').textContent='TAKE COMPLETE';return;}frame=requestAnimationFrame(tick);}
function start(){countTimer=null;$('countdown').hidden=true;playing=true;position=$('viewport').scrollTop;last=performance.now();keepAwake();status();frame=requestAnimationFrame(tick);}
function toggle(){if(playing||countTimer!==null){pause();return;}const v=$('viewport');if(v.scrollTop>=v.scrollHeight-v.clientHeight-1)reset();let count=Number(settings.delay);if(count){$('countdown').textContent=count;$('countdown').hidden=false;countTimer=setInterval(()=>{count--;if(count<=0){clearInterval(countTimer);start();}else $('countdown').textContent=count;},1000);status();}else start();}
async function launch(){document.body.classList.add('prompting');$('exit').hidden=false;$('expand').hidden=true;$('stageTitle').textContent=currentDoc().title||'UNTITLED SCRIPT';$('viewport').focus();try{if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();}catch{}position=$('viewport').scrollTop;}
function exit(){pause();document.body.classList.remove('prompting');$('exit').hidden=true;$('expand').hidden=false;$('stageTitle').textContent='STUDIO PREVIEW';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}
$('editor').addEventListener('input',saveDoc);$('title').addEventListener('input',saveDoc);$('scripts').onchange=()=>{current=$('scripts').value;loadDoc();};
$('new').onclick=()=>{const d={id:crypto.randomUUID(),title:'Untitled script',text:''};docs.push(d);current=d.id;loadDoc();$('title').focus();$('title').select();};
$('delete').onclick=()=>{if(!confirm(`Delete “${currentDoc().title||'Untitled script'}”?`))return;docs=docs.filter(d=>d.id!==current);if(!docs.length)docs.push({id:crypto.randomUUID(),title:'Untitled script',text:''});current=docs[0].id;loadDoc();};
document.querySelectorAll('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{$('editor').focus();document.execCommand(b.dataset.format);saveDoc();};});
$('editor').addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));saveDoc();});
for(const key of ['speed','size','width','delay','font','double','mirror','flip','showGuide'])$(key).addEventListener('input',()=>{settings[key]=$(key).type==='checkbox'?$(key).checked:key==='font'?$(key).value:Number($(key).value);apply();});
document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{settings.color=b.dataset.color;apply();});$('resetSettings').onclick=()=>{settings={...defaults};apply();};
$('play').onclick=toggle;$('top').onclick=reset;$('slower').onclick=()=>changeSpeed(-5);$('faster').onclick=()=>changeSpeed(5);$('launch').onclick=$('expand').onclick=launch;$('exit').onclick=exit;
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('prompting'))exit();return;}if(e.target.closest('input,textarea,select,[contenteditable="true"],dialog')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowUp'){e.preventDefault();changeSpeed(5);}else if(e.key==='ArrowDown'){e.preventDefault();changeSpeed(-5);}else if(e.code==='Space'){e.preventDefault();toggle();}else if(e.key.toLowerCase()==='t'){e.preventDefault();reset();}});
let pointer=null;$('viewport').addEventListener('pointerdown',e=>{pointer={y:e.clientY,moved:false};$('viewport').setPointerCapture(e.pointerId);});$('viewport').addEventListener('pointermove',e=>{if(!pointer)return;const delta=pointer.y-e.clientY;if(Math.abs(delta)>=24){pointer.moved=true;changeSpeed(delta>0?5:-5);pointer.y=e.clientY;}});$('viewport').addEventListener('pointerup',()=>{if(pointer&&!pointer.moved)toggle();pointer=null;});$('viewport').addEventListener('pointercancel',()=>pointer=null);$('viewport').addEventListener('scroll',()=>{if(!playing)position=$('viewport').scrollTop;progress();});$('viewport').addEventListener('wheel',()=>{if(playing)pause();},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&document.body.classList.contains('prompting'))exit();});
$('importBtn').onclick=()=>$('file').click();$('file').onchange=()=>{if($('file').files[0])importFile($('file').files[0]);$('file').value='';};
async function importFile(file){if(file.size>20*1024*1024){toast('Please use a document under 20 MB.');return;}try{let content;const ext=file.name.split('.').pop().toLowerCase();if(ext==='docx'){if(!window.mammoth)throw Error('Word importer could not load. Reload and try again.');content=(await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value;}else if(ext==='rtf')content=rtfToText(await file.text());else if(ext==='txt')content=await file.text();else throw Error('Use .docx, .rtf, or .txt. Save older .doc files as .docx first.');if(!content.trim())throw Error('No readable text found in this document.');const d={id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),text:content};docs.push(d);current=d.id;loadDoc();toast('Script imported. Ready for your next take.');}catch(e){toast('Import failed: '+e.message);}}
const panel=document.querySelector('.editor-panel');panel.addEventListener('dragover',e=>{e.preventDefault();});panel.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files[0])importFile(e.dataTransfer.files[0]);});
$('exportBtn').onclick=()=>{const blob=new Blob([text()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(currentDoc().title||'script').replace(/[\\/:*?"<>|]/g,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
loadDoc();apply();
